import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    y = [0] * n
    for i in range(n):
        x, v = data[1 + 2 * i:3 + 2 * i]
        y[x - 1] = v - 1

    # Each nonempty operation sequence has a set of pivots that is an
    # antichain: each chosen pivot must survive all later operations.
    # For an antichain, the common incomparable set is determined solely
    # by its leftmost and rightmost elements (in x order).
    reachable = {(1 << n) - 1}  # no operations
    for a in range(n):
        for b in range(a, n):
            if a != b and y[a] < y[b]:
                continue
            mask = 0
            for q in range(n):
                if q == a or q == b:
                    mask |= 1 << q
                    continue
                incomparable = True
                for p in (a, b):
                    if (q < p and y[q] < y[p]) or (q > p and y[q] > y[p]):
                        incomparable = False
                        break
                if incomparable:
                    mask |= 1 << q
            reachable.add(mask)
    print(len(reachable) % 998244353)

solve()

