import sys
MOD=998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    inf = n + 1

    # For each position p and left endpoint l, store the smallest R
    # among constraints with X=p and L >= l.
    min_r = [[inf] * (n + 2) for _ in range(n + 1)]
    k = 2
    for _ in range(m):
        L, R, X = data[k], data[k + 1], data[k + 2]
        k += 3
        if R < min_r[X][L]:
            min_r[X][L] = R
    for p in range(1, n + 1):
        row = min_r[p]
        for l in range(n, 0, -1):
            if row[l + 1] < row[l]:
                row[l] = row[l + 1]

    # Binomial coefficients account for interleaving the values assigned
    # to the left and right subintervals.
    comb = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        comb[i][0] = comb[i][i] = 1
        for j in range(1, i):
            comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

    dp = [[0] * (n + 2) for _ in range(n + 2)]
    for i in range(1, n + 2):
        dp[i][i - 1] = 1

    for length in range(1, n + 1):
        for l in range(1, n - length + 2):
            r = l + length - 1
            total = 0
            for p in range(l, r + 1):
                # A constraint with X=p wholly inside [l,r] would fail
                # if p is selected as the maximum of this interval.
                if min_r[p][l] > r:
                    left_size = p - l
                    total += comb[length - 1][left_size] * dp[l][p - 1] * dp[p + 1][r]
            dp[l][r] = total % MOD

    print(dp[1][n])

