from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        buckets = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            buckets[b].append((a, i))

        top1 = top2 = 0
        top_id = -1
        gains = [0] * len(conflictingPairs)
        base = 0

        for r in range(1, n + 1):
            for a, i in buckets[r]:
                if a > top1:
                    top2 = top1
                    top1 = a
                    top_id = i
                elif a == top1:
                    top2 = top1
                elif a > top2:
                    top2 = a

            base += r - top1
            if top_id >= 0 and top1 > top2:
                gains[top_id] += top1 - top2

        return base + max(gains)

