import sys, math

def main():
    d = list(map(int, sys.stdin.buffer.read().split()))
    if not d:
        return
    n, X = d[:2]
    v = d[2:]
    ps = [v[i * 4:i * 4 + 4] for i in range(n)]

    def cost(k, A, P, B, Q):
        mx = (k + A - 1) // A
        per = B // math.gcd(A, B)
        ans = 10**30
        for r in range(min(per, mx + 1)):
            top = r + ((mx - r) // per) * per
            xs = {r, top, max(r, top - per)}
            for x in xs:
                rem = k - A * x
                y = 0 if rem <= 0 else (rem + B - 1) // B
                ans = min(ans, P * x + Q * y)
        return ans

    def ok(k):
        s = 0
        for A, P, B, Q in ps:
            s += cost(k, A, P, B, Q)
            if s > X:
                return False
        return True

    lo, hi = 0, 100 * X + 1
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if ok(mid):
            lo = mid
        else:
            hi = mid
    print(lo)

main()

