class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        n = len(s)
        counts = [0] * (n + 1)
        prefix_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                rem = n - i - 1
                for j in range(rem + 1):
                    counts[prefix_ones + j] += comb(rem, j)
                prefix_ones += 1
        # values with exactly c set bits reduce in 1 + steps(c) operations.
        valid = [False] * (n + 1)
        for c in range(1, n + 1):
            t = c
            steps = 0
            while t != 1:
                t = t.bit_count()
                steps += 1
            valid[c] = (c == 1 or steps + 1 <= k)
        return sum(counts[c] for c in range(1, n + 1) if valid[c]) % MOD

