import sys

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        sys.setrecursionlimit(10000)
        n, m = len(grid), len(grid[0])
        # Screen-coordinate directions in clockwise order: SE, SW, NW, NE.
        dirs = ((1, 1), (1, -1), (-1, -1), (-1, 1))

        @lru_cache(None)
        def extend(r: int, c: int, d: int, want: int, can_turn: bool) -> int:
            if not (0 <= r < n and 0 <= c < m) or grid[r][c] != want:
                return 0
            next_want = 0 if want == 2 else 2
            dr, dc = dirs[d]
            best = extend(r + dr, c + dc, d, next_want, can_turn)
            if can_turn:
                td = (d + 1) % 4
                tr, tc = dirs[td]
                best = max(best, extend(r + tr, c + tc, td, next_want, False))
            return 1 + best

        answer = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] == 1:
                    answer = max(answer, 1)
                    for d, (dr, dc) in enumerate(dirs):
                        answer = max(answer, 1 + extend(r + dr, c + dc, d, 2, True))
        return answer

