import math

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = list(range(1, n + 1, 2))
        evens = list(range(2, n + 1, 2))
        no, ne = len(odds), len(evens)
        total = math.factorial(no) * math.factorial(ne)
        if no == ne:
            total *= 2
        if k > total:
            return []

        used = set()
        result = []
        last_parity = None
        for pos in range(n):
            for x in range(1, n + 1):
                if x in used:
                    continue
                parity = x % 2
                if last_parity is not None and parity == last_parity:
                    continue

                ro = no - sum(1 for y in used if y % 2 == 1) - (parity == 1)
                re = ne - sum(1 for y in used if y % 2 == 0) - (parity == 0)
                rem = n - pos - 1
                if rem == 0:
                    ways = 1
                else:
                    first = 1 - parity
                    a, b = (rem + 1) // 2, rem // 2
                    feasible = (ro == a and re == b) if first == 1 else (re == a and ro == b)
                    ways = math.factorial(ro) * math.factorial(re) if feasible else 0

                if k > ways:
                    k -= ways
                else:
                    result.append(x)
                    used.add(x)
                    last_parity = parity
                    break
            else:
                return []
        return result

