class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        p10 = [1] * n
        for i in range(1, n):
            p10[i] = p10[i - 1] * 10 % k

        coeff = []
        for i in range(m):
            j = n - 1 - i
            coeff.append((p10[i] + (p10[j] if j != i else 0)) % k)

        full = (1 << k) - 1

        def rotate(mask, shift):
            shift %= k
            if shift == 0:
                return mask
            return ((mask << shift) | (mask >> (k - shift))) & full

        # dp[i] has bit r set iff the suffix starting at i can contribute
        # residue r modulo k.
        dp = [0] * (m + 1)
        dp[m] = 1
        for i in range(m - 1, -1, -1):
            possible = 0
            for digit in range(10):
                possible |= rotate(dp[i + 1], digit * coeff[i])
            dp[i] = possible

        half = []
        remainder = 0
        for i, c in enumerate(coeff):
            for digit in range(9, -1, -1):
                if i == 0 and digit == 0:
                    continue
                needed = (-remainder - digit * c) % k
                if (dp[i + 1] >> needed) & 1:
                    half.append(str(digit))
                    remainder = (remainder + digit * c) % k
                    break

        half = ''.join(half)
        return half + (half[:-1][::-1] if n % 2 else half[::-1])

