from typing import List
class Solution:
 def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
  n=len(nums); size=4*n
  sm=[0]*size; lazy=[None]*size
  def apply(node,l,r,v): sm[node]=(r-l+1)*v; lazy[node]=v
  def push(node,l,r):
   if lazy[node] is not None and l<r:
    m=(l+r)//2; apply(node*2,l,m,lazy[node]); apply(node*2+1,m+1,r,lazy[node]); lazy[node]=None
  def upd(node,l,r,ql,qr,v):
   if ql<=l and r<=qr: apply(node,l,r,v); return
   push(node,l,r); m=(l+r)//2
   if ql<=m: upd(node*2,l,m,ql,qr,v)
   if qr>m: upd(node*2+1,m+1,r,ql,qr,v)
   sm[node]=sm[node*2]+sm[node*2+1]
  def query(node,l,r,ql,qr):
   if ql<=l and r<=qr:return sm[node]
   push(node,l,r); m=(l+r)//2; ans=0
   if ql<=m: ans+=query(node*2,l,m,ql,qr)
   if qr>m: ans+=query(node*2+1,m+1,r,ql,qr)
   return ans
  pref=[0]
  for x in nums:pref.append(pref[-1]+x)
  st=[]; ans=0
  for r,x in enumerate(nums):
   while st and nums[st[-1]]<=x: st.pop()
   p=st[-1] if st else -1
   upd(1,0,n-1,r,r,x)
   if p+1<=r:upd(1,0,n-1,p+1,r,x)
   st.append(r)
   lo,hi=0,r
   while lo<hi:
    mid=(lo+hi)//2
    cost=query(1,0,n-1,mid,r)-(pref[r+1]-pref[mid])
    if cost<=k:hi=mid
    else:lo=mid+1
   ans+=r-lo+1
  return ans

