class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)

        def occurrences(t):
            if not t:
                return list(range(n + 1))
            m = len(t)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j
            res = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    res.append(i - m + 1)
                    j = pi[j - 1]
            return res

        aa, bb, cc = occurrences(a), occurrences(b), occurrences(c)
        ans = n + 1
        for x in aa:
            yidx = bisect_left(bb, x + len(a))
            if yidx == len(bb):
                continue
            y = bb[yidx]
            zidx = bisect_left(cc, y + len(b))
            if zidx == len(cc):
                continue
            z = cc[zidx]
            ans = min(ans, z + len(c) - x)
        return -1 if ans == n + 1 else ans

