import sys

def solve_case(n, a, b):
    xs = [i for i, c in enumerate(a) if c == '1']
    ys = [i for i, c in enumerate(b) if c == '1']
    m = len(ys)
    if len(xs) < m:
        return -1

    def feasible(k):
        # Assign each source position to a target position. Assignments must be
        # nondecreasing, cover every target, and contract distances.
        dp = [False] * m
        for q, x in enumerate(xs):
            nd = [False] * m
            if q == 0:
                if abs(x - ys[0]) <= k:
                    nd[0] = True
            else:
                gap = x - xs[q - 1]
                for h in range(m):
                    if not dp[h]:
                        continue
                    if abs(x - ys[h]) <= k:
                        nd[h] = True
                    if h + 1 < m and ys[h + 1] - ys[h] <= gap and abs(x - ys[h + 1]) <= k:
                        nd[h + 1] = True
            dp = nd
        return dp[-1]

    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo if feasible(lo) else -1


