class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        post = []
        left = [0] * n
        right = [0] * n
        stack = [(0, 0)]
        while stack:
            v, exiting = stack.pop()
            if not exiting:
                left[v] = len(post)
                stack.append((v, 1))
                for u in reversed(children[v]):
                    stack.append((u, 0))
            else:
                post.append(s[v])
                right[v] = len(post)

        m = n
        odd = [0] * m
        l, r = 0, -1
        for i in range(m):
            k = 1 if i > r else min(odd[l + r - i], r - i + 1)
            while i - k >= 0 and i + k < m and post[i - k] == post[i + k]:
                k += 1
            odd[i] = k
            if i + k - 1 > r:
                l, r = i - k + 1, i + k - 1

        even = [0] * m
        l, r = 0, -1
        for i in range(m):
            k = 0 if i > r else min(even[l + r - i + 1], r - i + 1)
            while i - k - 1 >= 0 and i + k < m and post[i - k - 1] == post[i + k]:
                k += 1
            even[i] = k
            if i + k - 1 > r:
                l, r = i - k, i + k - 1

        ans = [False] * n
        for v in range(n):
            a, b = left[v], right[v]
            length = b - a
            if length & 1:
                ans[v] = odd[(a + b - 1) // 2] >= (length + 1) // 2
            else:
                ans[v] = even[(a + b) // 2] >= length // 2
        return ans

