class Solution:
    def maxEnergyBoost(self, energyDrinkA: List[int], energyDrinkB: List[int]) -> int:
        # Best total ending with A/B at the preceding hour and the hour before it.
        a_two = b_two = 0
        a_prev = b_prev = 0

        for a_value, b_value in zip(energyDrinkA, energyDrinkB):
            a_current = a_value + max(a_prev, b_two)
            b_current = b_value + max(b_prev, a_two)
            a_two, a_prev = a_prev, a_current
            b_two, b_prev = b_prev, b_current

        return max(a_prev, b_prev)

