from collections import Counter

class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        total = sum(nums)
        counts = Counter(nums)
        answer = None

        for outlier in counts:
            remainder = total - outlier
            if remainder % 2 != 0:
                continue

            sum_value = remainder // 2
            required = 2 if outlier == sum_value else 1
            if counts[sum_value] >= required:
                if answer is None or outlier > answer:
                    answer = outlier

        return answer

