import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        limit = 10000
        prime = [True] * limit
        prime[0] = prime[1] = False
        for p in range(2, 100):
            if prime[p]:
                for x in range(p * p, limit, p):
                    prime[x] = False

        if prime[n] or prime[m]:
            return -1

        inf = 10**30
        dist = [inf] * limit
        dist[n] = n
        pq = [(n, n)]

        while pq:
            cost, x = heapq.heappop(pq)
            if cost != dist[x]:
                continue
            if x == m:
                return cost

            digits = list(str(x))
            for i, ch in enumerate(digits):
                d = int(ch)
                for nd in (d - 1, d + 1):
                    if not 0 <= nd <= 9:
                        continue
                    changed = digits.copy()
                    changed[i] = str(nd)
                    y = int(''.join(changed))
                    if not prime[y] and cost + y < dist[y]:
                        dist[y] = cost + y
                        heapq.heappush(pq, (dist[y], y))

        return -1

