from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)

        # Z[i] is the common-prefix length of nums and nums[i:].
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z[i] = min(right - i, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > right:
                left, right = i, i + z[i]

        answer = 0

        # nums1 is a prefix of nums2. For a fixed |nums1|=i, valid
        # second-subarray endpoints are j >= 2*i.
        for i in range(1, n):
            if z[i] >= i:
                answer += max(0, n - 2 * i)

        # nums2 is a prefix of nums3. For gap d=j-i, compare the
        # length-d segments beginning at i and i+d. Scan each diagonal;
        # the running match length gives the LCP for that pair.
        for d in range(1, n - 1):
            run = 0
            for i in range(n - d - 1, 0, -1):
                if nums[i] == nums[i + d]:
                    run += 1
                else:
                    run = 0
                if run >= d:
                    # Exclude splits already counted by the first condition.
                    if not (d >= i and z[i] >= i):
                        answer += 1

        return answer

