from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n, m = len(source), len(pattern)
        targets = set(targetIndices)
        neg = -10**9
        dp = [neg] * (m + 1)
        dp[0] = 0

        for i, c in enumerate(source):
            ndp = [neg] * (m + 1)
            can_delete = i in targets
            for j, val in enumerate(dp):
                if val == neg:
                    continue
                if can_delete and val + 1 > ndp[j]:
                    ndp[j] = val + 1
                if val > ndp[j]:
                    ndp[j] = val
                if j < m and c == pattern[j] and val > ndp[j + 1]:
                    ndp[j + 1] = val
            dp = ndp

        return dp[m]

