import heapq
class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        rev=[[] for _ in range(n)]
        for a,b,w in edges:
            rev[b].append((a,w))
        inf=10**18
        d=[inf]*n
        d[0]=0
        pq=[(0,0)]
        while pq:
            cost,u=heapq.heappop(pq)
            if cost!=d[u]: continue
            for v,w in rev[u]:
                nc=max(cost,w)
                if nc<d[v]:
                    d[v]=nc
                    heapq.heappush(pq,(nc,v))
        ans=max(d)
        return -1 if ans==inf else ans

